// The require below names a module that does not exist. It is hidden inside a
// function that is never called, but the CommonJS parser still detects the
// require statically. The bundler must tolerate the unresolved module (which
// the compartment mapper records as a "deferred error") instead of aborting the
// whole bundle: because the function is never called, the missing module is
// never reached and must not throw.
function unreachable() {
  // eslint-disable-next-line no-unused-vars
  const require = () => {};
  require('./does-not-exist');
}

module.exports = { ok: true };
